import { Box } from "@mui/material";
import React from "react";
import { useState } from "react";
import { useEffect, useRef } from "react";
import BannerSection from "src/views/pages/home/BannerSection";
import JourneyAndValues from "src/views/pages/home/JourneyAndValues";
import Questions from "src/views/pages/home/Questions";
import UnlockFutureInnovation from "src/views/pages/home/UnlockFutureInnovation";
import UpComingEvents from "src/views/pages/home/UpComingEvents";
import bgImg from "../../assets/images/section1BgImg.png";
import bgImgSmall from "../../assets/images/bannerSectionBgImgSmall.png";
import "../../styles/animation.css";

const HomePage = () => {
  useEffect(() => {
    window.scrollTo(0, 0); // Scroll to the top when the component mounts
  }, []);

  const [backgroundPositionY, setBackgroundPositionY] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      const offset = window.pageYOffset || document.documentElement.scrollTop;
      setBackgroundPositionY(offset); // Set the background position directly based on scroll offset
    };

    window.addEventListener("scroll", handleScroll);
    handleScroll(); // Initialize position

    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);

  return (
    <>
      <Box
        sx={{
          position: "relative",
          minHeight: "100vh",
          overflowX: "hidden",
          overflowY: "auto",
          scrollBehavior: "smooth",
          transition: "2s ease-in-out",
        }}
      >
        <Box
          sx={{
            backgroundImage: { xs: `url(${bgImgSmall})`, sm: `url(${bgImg})` },
            backgroundRepeat: "no-repeat",
            backgroundPosition: `right ${backgroundPositionY}px`,
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            zIndex: -1,
            pointerEvents: "none",
            transition: "background-position 1.5s ease-in-out",
          }}
        />
        <Box sx={{ position: "relative", zIndex: 1 }}>
          <BannerSection />
          <Box
            sx={{
              transform: {
                xs: "translate(0px, -4px)",
                sm: "translate(0px, -10px)",
                md: "translate(0px, -20px)",
                lg: "translate(0px, -30px)",
                xl: "translate(0px, -40px)",
              },
            }}
          >
            <JourneyAndValues />
          </Box>
          <UnlockFutureInnovation />
          <UpComingEvents />
          <Questions />
        </Box>
      </Box>
    </>
  );
};

export default HomePage;
