import React, { useState } from "react";
import {
  Typography,
  Box,
  Container,
  Grid,
  Button,
  Accordion,
  AccordionActions,
  AccordionSummary,
  AccordionDetails,
} from "@mui/material";
import CancelIcon from "@mui/icons-material/Cancel";
import { useEffect } from "react";
import { useRef } from "react";
import bgImg from "../../../assets/images/section1BgImg.png";
import ScrollAnimation from "react-animate-on-scroll";

const Questions = () => {
  const questions = [1, 2, 3, 4];
  const [expanded, setExpanded] = useState(false);
  const handleChange = (index) => {
    setExpanded((prev) => ({ ...prev, [index]: !prev[index] }));
  };
  const [isInView, setIsInView] = useState(false);
  const containerRef = useRef(null);
  useEffect(() => {
    const containerObserver = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setIsInView(true);
          } else {
            setIsInView(false);
          }
        });
      },
      { threshold: 0.1 } // Adjust threshold as needed
    );

    if (containerRef.current) {
      containerObserver.observe(containerRef.current);
    }

    return () => {
      if (containerRef.current) {
        containerObserver.unobserve(containerRef.current);
      }
    };
  }, []);
  return (
    <>
      <Box sx={{ overflow: "hidden" }}>
        <Container
          maxWidth={"xl"}
          sx={{
            px: { xs: 5, sm: 10, lg: 15, xl: 20 },
            pt: { xs: 5, sm: 10, lg: 15, xl: 20 },
            pb: { xs: 10, md: 0 },
          }}
        >
          <Grid
            container
            rowSpacing={{ xs: 5, md: 0 }}
            columnSpacing={{ md: 25, lg: 30, xl: 35 }}
          >
            <Grid item container md={5.5}>
              <Box sx={{ display: "flex", flexDirection: "column", gap: 4 }}>
                <ScrollAnimation animateIn="fade-in-right " animateOnce>
                  <Typography
                    sx={{
                      fontSize: {
                        xs: "26px",
                        sm: "36px",
                        md: "46px",
                        lg: "56px",
                      },
                      fontWeight: 500,
                      lineHeight: {
                        xs: "34px",
                        sm: "44px",
                        md: "55px",
                        lg: "70px",
                      },
                      color: "#201D28",
                      width: { md: "200px" },
                    }}
                  >
                    Got Any Questions?
                  </Typography>
                </ScrollAnimation>
                <ScrollAnimation animateIn="fade-in-right " animateOnce>
                  <Typography
                    sx={{
                      fontSize: {
                        xs: "14px",
                        sm: "16px",
                        lg: "18px",
                      },
                      lineHeight: {
                        xs: "22px",
                        sm: "25px",
                        lg: "30px",
                      },
                      fontWeight: 500,
                      color: "#646271",
                    }}
                  >
                    Find answers to common questions about our services,
                    processes, and how we can help your business thrive. Our
                    FAQs are here to provide you with the information you need
                    quickly and easily.
                  </Typography>
                </ScrollAnimation>
              </Box>
            </Grid>
            <Grid
              item
              md={6.5}
              sx={{ display: "flex", flexDirection: "column", gap: 4 }}
            >
              {questions.map((item, index) => (
                <ScrollAnimation
                  animateIn="fade-in-up-questions"
                  animateOut="fade-out-down-questions"
                  key={index}
                >
                  <Accordion
                    square="false"
                    expanded={expanded[index]}
                    onChange={() => handleChange(index)}
                    sx={{
                      boxShadow: "none",
                      "&::before": {
                        content: "none", // Remove the line
                      },
                      py: 2,
                      border: "1px solid #CACACA",
                      borderRadius: "22px",
                      "&.Mui-expanded": {
                        borderRadius: "27px",
                        border: 0,
                        bgcolor: "#F5F5F9",
                        boxShadow: "none",
                        "& .MuiAccordionSummary-root": {
                          borderRadius: "27px",
                          margin: "0px 0",
                        },
                      },
                    }}
                  >
                    <AccordionSummary
                      expandIcon={
                        expanded[index] ? (
                          <CancelIcon
                            sx={{ color: "#602DE1", fontSize: "30px" }}
                          />
                        ) : (
                          ""
                        )
                      }
                      sx={{
                        fontSize: {
                          xs: "18px",
                          md: "20px",
                        },
                        lineHeight: {
                          xs: "26px",
                          md: "30px",
                        },
                        fontWeight: 600,
                        color: "#201D28",
                      }}
                    >
                      Lorem ipsum dolor sit amet, consectetur?
                    </AccordionSummary>
                    <AccordionDetails
                      sx={{
                        fontSize: {
                          xs: "14px",
                          sm: "16px",
                          lg: "18px",
                        },
                        lineHeight: {
                          xs: "22px",
                          sm: "25px",
                          lg: "30px",
                        },
                        fontWeight: 400,
                        color: "#646271",
                      }}
                    >
                      Lorem ipsum dolor sit amet, consectetur adipiscing elit.
                      Suspendisse malesuada lacus ex, sit amet blandit leo
                      lobortis eget.
                    </AccordionDetails>
                  </Accordion>
                </ScrollAnimation>
              ))}
            </Grid>
          </Grid>
        </Container>
      </Box>
    </>
  );
};

export default Questions;
